#include "viewer.h"
#include "ui_generated.h"
#include <cmath>
namespace spng {
Viewer::Viewer(QWidget* parent):QMainWindow(parent){
    buildReferenceUi(this,objects);view=get<ImageView>("view");pool.setMaxThreadCount(2);
    lastOpenDir=QCoreApplication::applicationDirPath();auto ex=QDir(lastOpenDir).filePath("exports");lastSaveDir=QDir(ex).exists()?ex:lastOpenDir;
    debounce.setSingleShot(true);debounce.setInterval(35);connect(&debounce,&QTimer::timeout,this,&Viewer::loadRequestedLayer);
    playTimer.setSingleShot(true);connect(&playTimer,&QTimer::timeout,this,&Viewer::playTick);
    for(auto& item:centerCross){item=new QGraphicsLineItem;QPen p(QColor("#20cfe4"),1);p.setCosmetic(true);item->setPen(p);item->setZValue(20);item->hide();view->scene()->addItem(item);}
    bindControls();updateControls();
}
Viewer::~Viewer(){closing=true;if(cancellation)cancellation->store(true);pool.waitForDone();}
void Viewer::setCombo(QComboBox* c,QStringList texts,QString preferred,QStringList data){QSignalBlocker blocked(c);c->clear();for(int i=0;i<texts.size();i++)c->addItem(texts[i],data.isEmpty()?texts[i]:data[i]);int index=c->findText(preferred);c->setCurrentIndex(index>=0?index:texts.empty()?-1:0);if(c->isEditable()&&texts.empty())c->setEditText("");c->setEnabled(!texts.empty());}
static QStringList sortedUnique(QStringList a){a.removeDuplicates();std::sort(a.begin(),a.end(),naturalLess);return a;}
void Viewer::openPath(const QString& p){auto info=QFileInfo(p);QString path=info.absoluteFilePath();lastOpenDir=info.isDir()?path:info.absolutePath();invalidate({"root","sensors","files","open","frame"});clearStack();for(auto n:{"container_combo","sensor_combo","layer_combo","kind_combo","view_combo","file_combo"})setCombo(combo(n),{});records.clear();label("source_label")->setText(fontMetrics().elidedText(QDir::toNativeSeparators(path),Qt::ElideMiddle,340));label("source_label")->setToolTip(path);if(info.isDir()){label("state_label")->setText("フォルダを確認中…");run("root",[path]{return discoverRoot(path);},[this](NamedPaths paths){QStringList names,data;for(auto p:paths){names<<p.first;data<<p.second;}setCombo(combo("container_combo"),names,{},data);containerChanged();});}else openStack(path);}
void Viewer::containerChanged(){QString path=combo("container_combo")->currentData().toString();if(path.isEmpty())return;invalidate({"sensors","files","open","frame"});clearStack();for(auto n:{"sensor_combo","layer_combo","kind_combo","view_combo","file_combo"})combo(n)->setEnabled(false);label("state_label")->setText("センサーを確認中…");run("sensors",[path]{return discoverSensors(path);},[this](NamedPaths paths){QStringList names,data;for(auto p:paths){names<<p.first;data<<p.second;}setCombo(combo("sensor_combo"),names,{},data);sensorChanged();});}
void Viewer::sensorChanged(){QString path=combo("sensor_combo")->currentData().toString();if(path.isEmpty())return;invalidate({"files","open","frame"});clearStack();for(auto n:{"layer_combo","kind_combo","view_combo","file_combo"})combo(n)->setEnabled(false);label("state_label")->setText("このセンサーのファイルを一覧中…");run("files",[path]{return listSensorFiles(path);},[this](QVector<FileRecord> value){auto old=combo("layer_combo")->currentText();records=value;QStringList layers;for(auto r:records)layers<<r.layer;setCombo(combo("layer_combo"),sortedUnique(layers),old);layerChanged();if(records.empty())label("state_label")->setText("このセンサーにはspngがありません。別のセンサーまたはフォルダを選んでください。");});}
void Viewer::layerChanged(){auto layer=combo("layer_combo")->currentText();QStringList kinds;for(auto r:records)if(r.layer==layer)kinds<<r.kind;kinds=sortedUnique(kinds);QString preferred=combo("kind_combo")->currentText();if(!kinds.contains(preferred)){preferred.clear();for(auto k:kinds)if(k.startsWith("raw",Qt::CaseInsensitive)){preferred=k;break;}}setCombo(combo("kind_combo"),kinds,preferred);kindChanged();}
void Viewer::kindChanged(){QStringList views;for(auto r:records)if(r.layer==combo("layer_combo")->currentText()&&r.kind==combo("kind_combo")->currentText())views<<r.view;setCombo(combo("view_combo"),sortedUnique(views),combo("view_combo")->currentText());viewChanged();}
void Viewer::typedView(){auto c=combo("view_combo");QString text=c->currentText().trimmed();bool ok;auto n=text.toLongLong(&ok);if(ok)text=QString::number(n);int index=c->findText(text,Qt::MatchExactly);if(index<0){label("state_label")->setText("View "+text+" は、このLayer・画像種別にはありません。");return;}if(index==c->currentIndex())viewChanged();else c->setCurrentIndex(index);}
void Viewer::viewChanged(){QStringList names,data;for(auto r:records)if(r.layer==combo("layer_combo")->currentText()&&r.kind==combo("kind_combo")->currentText()&&r.view==combo("view_combo")->currentText()){names<<QFileInfo(r.path).fileName();data<<r.path;}setCombo(combo("file_combo"),names,{},data);fileChanged();}
void Viewer::fileChanged(){auto path=combo("file_combo")->currentData().toString();if(path.isEmpty())clearStack();else openStack(path);}
void Viewer::clearStack(){
    invalidateScanParameters();stopPlay();if(cancellation)cancellation->store(true);bulkSerial++;invalidate({"bulk","frame"});bulkRunning=false;
    rawBank.reset();processed.reset();projection.reset();points[0].reset();points[1].reset();
    {QSignalBlocker b(combo("stage_combo"));combo("stage_combo")->clear();combo("stage_combo")->addItem("元画像");}{QSignalBlocker b(check("follow_check"));check("follow_check")->setChecked(false);}
    for(auto item:centerCross)item->hide();label("track_label")->setText("2点未登録");label("process_info")->setText("処理は未適用。");get<QProgressBar>("progress_bar")->hide();button("cancel_button")->hide();
    debounce.stop();stack.reset();image={};loadedIndex=-1;currentPath.clear();frameCache.clear();cacheOrder.clear();cacheBytes=0;view->trackingActive=false;view->clearImage();levelsInitialized=false;loadingImage=false;
    label("meta")->setText("画像なし");label("roi_label")->setText("範囲未選択");label("filename")->setText("画像を選択してください。");label("layer_range")->setText("/ ―");updateControls();
}
void Viewer::openStack(const QString& path){invalidate({"open","frame"});clearStack();currentPath=path;label("filename")->setText(QFileInfo(path).fileName());label("filename")->setToolTip(path);label("state_label")->setText("層の索引を読み込み中…");setWindowTitle(QFileInfo(path).fileName()+" — SPNG Viewer");run("open",[path]{return std::make_shared<Stack>(path);},[this](auto value){stackReady(value);});}
void Viewer::stackReady(std::shared_ptr<Stack> value){stack=value;int n=int(stack->frames.size())-1;spin("play_start")->setMaximum(n);spin("play_end")->setMaximum(n);spin("point0_z")->setMaximum(n);spin("point1_z")->setMaximum(n);spin("play_start")->setValue(0);spin("play_end")->setValue(n);get<QLineEdit>("layer_spec")->setText(QString("0-%1").arg(n));{QSignalBlocker b(get<QSlider>("layer_slider"));get<QSlider>("layer_slider")->setRange(0,n);get<QSlider>("layer_slider")->setValue(stack->firstAvailable());}{QSignalBlocker b(spin("layer_number"));spin("layer_number")->setRange(0,n);spin("layer_number")->setValue(stack->firstAvailable());}label("layer_range")->setText(QString("/ 0-%1").arg(n));updateControls();loadRequestedLayer();if(imageLayer(currentPath)<0){QSignalBlocker b(spin("scan_layer"));spin("scan_layer")->setValue(-1);}reloadScanParameters();}
void Viewer::requestLayer(){projection.reset();invalidate({"frame"});image={};loadedIndex=-1;loadingImage=true;cursorPosition();label("state_label")->setText(QString("層 %1 を読み込み中…").arg(spin("layer_number")->value()));updateControls();debounce.start();if(playing){debounce.stop();loadRequestedLayer();}}
void Viewer::stepLayer(int step){if(stack)spin("layer_number")->setValue(std::clamp(spin("layer_number")->value()+step,0,int(stack->frames.size())-1));}
void Viewer::loadRequestedLayer(){if(!stack)return;projection.reset();int index=spin("layer_number")->value();loadingImage=true;updateControls();if(stage()=="元画像"&&!rawBank&&frameCache.contains(index)){cacheOrder.removeAll(index);cacheOrder.append(index);frameReady(index,frameCache.value(index));return;}auto read=reader();run("frame",[read,index]{return QPair<int,Image>{index,read(index)};},[this](auto p){frameReady(p.first,p.second);});}
void Viewer::frameReady(int index,Image value){
    if(!stack||index!=spin("layer_number")->value())return;loadingImage=false;QSize before=view->imageSize;image=value;loadedIndex=index;
    if(image.empty()){view->clearImage();label("state_label")->setText(QString("層 %1 は未保存・欠損です。別の層を選択してください。").arg(index));label("meta")->setText(QString("%1 層（0-%2）／ この層は欠損").arg(stack->frames.size()).arg(stack->frames.size()-1));label("roi_label")->setText("範囲未選択");updateControls();schedulePlay();return;}
    if(stage()=="元画像"&&!rawBank&&!frameCache.contains(index)){quint64 amount=image.pixels.total()*image.pixels.elemSize(),limit=96*1024*1024;if(amount<=limit){while(!cacheOrder.empty()&&(cacheBytes+amount>limit||cacheOrder.size()>=8)){auto old=frameCache.take(cacheOrder.takeFirst());cacheBytes-=old.pixels.total()*old.pixels.elemSize();}frameCache[index]=image;cacheOrder.append(index);cacheBytes+=amount;}}
    if(!levelsInitialized){levelsInitialized=true;auto levels=defaultLevels(image);setLevels(levels.first,levels.second);}
    view->pixmapItem->setOpacity(1);view->setImage(displayImage(image,real("low")->value(),real("high")->value(),check("invert")->isChecked()),before!=image.size());if(view->roi)view->roiItem->show();else label("roi_label")->setText("範囲未選択");
    spin("roi_x")->setMaximum(image.size().width()-1);spin("roi_y")->setMaximum(image.size().height()-1);spin("roi_w")->setMaximum(image.size().width());spin("roi_h")->setMaximum(image.size().height());
    QHash<QString,QString> modes={{"L","8bitグレースケール"},{"1","1bit二値"},{"RGB","RGBカラー"},{"RGBA","RGBカラー＋透明度"},{"LA","グレースケール＋透明度"},{"P","パレットカラー"}};int missing=0;for(auto f:stack->frames)missing+=f.missing();auto record=stack->frames[index];QString mode=modes.value(image.mode,QString("%1bitグレースケール").arg(record.depth));
    label("meta")->setText(QString("%1 × %2 pixel　／　PNG %3 bit\n%4 層（0-%5）　欠損 %6 層\n形式：%7　／　原点：左下").arg(image.size().width()).arg(image.size().height()).arg(record.depth).arg(stack->frames.size()).arg(stack->frames.size()-1).arg(missing).arg(mode));
    label("state_label")->setText(QString("層 %1 / 0-%2　表示中").arg(index).arg(stack->frames.size()-1));label("filename")->setText(QFileInfo(currentPath).fileName()+"　／　"+stage());if(stage()!="元画像")label("meta")->setText(label("meta")->text().section("\n形式：",0,0)+QString("\n表示：%1（処理後）　／　原点：左下").arg(stage()));updateControls();centerFollow();schedulePlay();
}
void Viewer::setLevels(double low,double high){QSignalBlocker a(real("low")),b(real("high"));real("low")->setValue(low);real("high")->setValue(high);}
void Viewer::resetLevels(){if(image.empty())return;auto p=defaultLevels(image);setLevels(p.first,p.second);{QSignalBlocker b(check("invert"));check("invert")->setChecked(false);}refreshDisplay();}
void Viewer::refreshDisplay(){if(image.empty())return;if(real("low")->value()>=real("high")->value()){label("state_label")->setText("白に対応する値を、黒に対応する値より大きくしてください。");return;}view->setImage(displayImage(image,real("low")->value(),real("high")->value(),check("invert")->isChecked()));}
void Viewer::applyRoi(){if(image.empty())return;try{view->setRoi(bottomLeftRoi(spin("roi_x")->value(),spin("roi_y")->value(),spin("roi_w")->value(),spin("roi_h")->value(),image.size()));}catch(const std::exception&e){QMessageBox::warning(this,"範囲を確認してください",QString::fromUtf8(e.what()));}}
void Viewer::roiChanged(){if(!view->roi||image.empty()){label("roi_label")->setText("範囲未選択");updateControls();return;}auto r=*view->roi;int x=r.x(),y=image.size().height()-r.y()-r.height(),w=r.width(),h=r.height();for(auto p:{QPair<const char*,int>{"roi_x",x},{"roi_y",y},{"roi_w",w},{"roi_h",h}}){QSignalBlocker b(spin(p.first));spin(p.first)->setValue(p.second);}label("roi_label")->setText(QString("左下 (%1, %2)　／　%3 × %4 pixel\nX: %1-%5、Y: %2-%6").arg(x).arg(y).arg(w).arg(h).arg(x+w-1).arg(y+h-1));updateControls();}
void Viewer::cursorPosition(QPointF p,bool valid){QString text="カーソル［左下原点・pixel］ X: ―　Y: ―　画素値: ―";if(valid&&!image.empty()){int x=int(std::floor(p.x())),top=int(std::floor(p.y()));if(x>=0&&top>=0&&x<image.size().width()&&top<image.size().height()){int y=image.size().height()-1-top;text=QString("カーソル［左下原点・pixel］ X: %1　Y: %2　画素値: %3").arg(x).arg(y).arg(pixelText(image,x,top));if(projection)text=QString("カーソル［左下原点・pixel］ X: %1　Y: %2　値: %3　選択層: %4").arg(x).arg(y).arg(pixelText(projection->values,x,top)).arg(projection->layers.at<int>(top,x));}}label("cursor_label")->setText(text);}
void Viewer::jobError(QString channel,QString error){loadingImage=false;if(channel=="bulk"){bulkRunning=false;get<QProgressBar>("progress_bar")->hide();button("cancel_button")->hide();updateControls();label("state_label")->setText(error);if(error!="処理を中止しました。")QMessageBox::warning(this,"処理できませんでした",error);if(image.empty()&&stack)loadRequestedLayer();return;}if(channel=="open"||channel=="frame"){image={};loadedIndex=-1;view->clearImage();}label("state_label")->setText("読み込みに失敗しました。");updateControls();QMessageBox::warning(this,"読み込みエラー",error);}
void Viewer::dragEnterEvent(QDragEnterEvent* e){for(auto u:e->mimeData()->urls())if(u.isLocalFile()){e->acceptProposedAction();return;}}
void Viewer::dropEvent(QDropEvent* e){for(auto u:e->mimeData()->urls())if(u.isLocalFile()){openPath(u.toLocalFile());e->acceptProposedAction();return;}}
void Viewer::closeEvent(QCloseEvent* e){closing=true;stopPlay();debounce.stop();if(cancellation)cancellation->store(true);invalidate({"root","sensors","files","open","frame","params","bulk"});pool.waitForDone();rawBank.reset();processed.reset();e->accept();}
}
